choose.when:
SELECT task_order.id, task_order.order_number, task_order.task_type_enum, cut_config.id 'cut_config.id', cut_config.`name` 'cut_config.name', task.quantity, task.total_net_weight, task.total_gross_weight, task.complete_quantity, task.total_complete_net_weight, task.total_complete_gross_weight FROM mes_building_task_order task_order LEFT JOIN ( SELECT task_order_id, IFNULL( sum( quantity ), 0 ) quantity, IFNULL( sum( complete_quantity ), 0 ) complete_quantity, IFNULL( sum( total_net_weight ), 0 ) total_net_weight, IFNULL( sum( total_gross_weight ), 0 ) total_gross_weight, IFNULL( sum( total_complete_net_weight ), 0 ) total_complete_net_weight, IFNULL( sum( total_complete_gross_weight ), 0 ) total_complete_gross_weight FROM ( SELECT task.task_order_id, task.task_quantity quantity, task.complete_quantity complete_quantity, task.task_quantity * product.net_weight total_net_weight, task.task_quantity * product.gross_weight total_gross_weight, task.complete_quantity * product.net_weight total_complete_net_weight, task.complete_quantity * product.gross_weight total_complete_gross_weight FROM mes_building_task task LEFT JOIN tech_machine_part product ON task.product_id = product.id WHERE task_type_enum = 1 AND task.task_quantity <> task.in_production_quantity AND task.bool_delete_enum = 0 ) task GROUP BY task.task_order_id ) task ON task.task_order_id = task_order.id LEFT JOIN mes_building_cut_config cut_config ON task_order.cut_config_id = cut_config.id WHERE task_order.id IN ( SELECT task_order_id FROM mes_building_nest_cut_plate WHERE id IN ( SELECT mes_building_nest_cut_plate_id FROM mes_building_nest_cut_plate_part
WHERE part_id IN ( SELECT id FROM tech_machine_part WHERE project_id = #{projectId} )
)AND bool_issue_enum = 1 AND bool_production_eunm = 0 )
